from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    od = OrderedDict()  # key -> value
    expiry = {}         # key -> expiration time (write_time + ttl)
    results = []

    def purge_expired(t):
        for k in list(od.keys()):
            if expiry[k] <= t:
                del od[k]
                del expiry[k]

    for op in ops:
        kind = op[0]
        t = op[1]
        key = op[2]

        purge_expired(t)

        if kind == 'put':
            value = op[3]
            if key in od:
                # key exists and is valid (not expired) - just update
                od[key] = value
                expiry[key] = t + ttl
                od.move_to_end(key)
            else:
                # key absent - may need eviction
                if len(od) >= capacity:
                    od.popitem(last=False)
                    # also remove its expiry entry
                    # (we don't know its key here directly, but popitem returns it)
                od[key] = value
                expiry[key] = t + ttl
                od.move_to_end(key)
        elif kind == 'get':
            if key in od:
                val = od[key]
                od.move_to_end(key)
                results.append(val)
            else:
                results.append(-1)

    return results

